interface CmpSite extends Site { name: string }
interface Doc extends Omit<SitesDoc, "sites" | "window"> { sites: CmpSite[]; window: { start_utc: string } }
interface Scenario { site: string; start: string; hours: number }
type Metrics = ScenarioMetrics | null;

/** Renders a template into detached DOM nodes. Preact is only a template engine here: nothing re-renders them. */
function build(v: ComponentChild): ChildNode[] {
  const c = document.createElement("div"); render(v, c); return [...c.childNodes];
}
const one = (v: ComponentChild): HTMLElement => build(v)[0] as HTMLElement;
/**
 * Embeds a DOM node built by the core (seals, bars, layer cards). The <mp-node> placeholder is swapped for the node
 * itself as soon as it is mounted, so the final DOM has no wrapper (child selectors in the CSS keep matching).
 */
function Node({ node }: { node: Node | null }) {
  return h("mp-node" as "span", { ref: (host: HTMLElement | null) => { if (host && node) host.replaceWith(node); } });
}

const LETTERS = ["A", "B", "C"];
const DAY = 24, MAXSC = 3;
const $ = (id: string) => document.getElementById(id) as HTMLElement;
const shell = mountShell({ screen: "compare", context: null, onLang: () => { paintContext(); draw(); } });
mountSheet($("sheet"));
const doc = (await loadSites()) as unknown as Doc;
const siteOf = (id: string): CmpSite | undefined => doc.sites.find(s => s.id === id);
const hoursDefault = (): number => getState().hours || 14 * DAY;
const t0Default = (): string => getState().start || doc.window.start_utc;

/** Scenarios from the URL hash; defaults derive from the data (first site, second site, second site two windows later). */
function scenarios(): Scenario[] {
  const hs = parseHash(location.hash).sc.filter(s => siteOf(s.site));
  if (hs.length) return hs.map(s => ({ site: s.site, start: s.start || t0Default(), hours: s.hours || hoursDefault() }));
  const ids = doc.sites.map(s => s.id), hrs = hoursDefault(), a = t0Default();
  const later = new Date(Date.parse(a) + 2 * hrs * HOUR_MS).toISOString();
  const selectedSite = getState().site;
  const first = selectedSite && ids.includes(selectedSite) ? selectedSite : ids[0];
  const second = ids.find(id => id !== first) || first;
  return [{ site: first, start: a, hours: hrs }, { site: second, start: a, hours: hrs }, { site: second, start: later, hours: hrs }].slice(0, Math.min(MAXSC, 3));
}
let sel = 0;
// First paint (mobile LCP): the context bar comes from the URL hash and the catalogue (seal, window), and the panels show
// the loading shimmer (scenario.css). Only after that paint do the hourly series (280 KB each) and the API figures start:
// Compare needs the series of the sites in the visible scenarios (up to 3) and of nobody else; a site chosen later in the
// editor is fetched then. Screen state is declared before the first await: the data callbacks may fire while it starts.
let online: boolean | null = null, drawRev = 0;
const onlineP = apiOnline().then(v => { online = v; paintContext(); return v; });
/** The hourly series of a site, fetched on demand (one download per site, shared with every other caller). */
function seriesOf(id: string): Promise<SiteSeriesLike> { return loadSeries(siteOf(id) as CmpSite); }
function paintContext() {
  const list = scenarios(), cur = Math.min(sel, list.length - 1);
  const dates = new Set(list.map(s => s.start)).size, sites = new Set(list.map(s => s.site)).size;
  shell.setContext({ site: t("cmp.ctx", { n: list.length, s: sites }), date: t("cmp.dates", { n: dates }), days: fmtNum(list[cur].hours / DAY),
    seal: ctxSeal ?? sealFor(doc.status), online, action: { label: t("cmp.delay", { L: LETTERS[cur] }), href: recoverHref(list) } });
}
let ctxSeal: string | null = null;
const save = (list: Scenario[]) => { history.replaceState(null, "", location.search + "#" + buildHash({ sc: list })); draw(); };

async function metricsFor(sc: Scenario): Promise<Metrics> {
  const startMs = Date.parse(sc.start);
  if (online) { const r = await apiCompareMetrics(sc.site, new Date(startMs).toISOString(), sc.hours); if (r.metrics) return r.metrics; }
  return staticMetrics(await seriesOf(sc.site), startMs, sc.hours, doc.status, sc.site);
}
const fmtDate = (ms: number): string => new Intl.DateTimeFormat(lang(), { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }).format(ms);
const hv = (x: number | null | undefined): string => (x == null ? t("nd") : fmtNum(x, 0) + " h");
const pv = (x: number | null | undefined): string => (x == null ? t("nd") : fmtNum(x, 0) + "%");

const ndSeal = () => <Node node={sealEl("N/D")} />;

async function draw() {
  const rev = ++drawRev;
  const list = scenarios(); if (sel >= list.length) sel = 0;
  const st = getState(), rules: LimitRules = { night: st.night, blackout: st.blackout };
  const seriesP = seriesOf(list[sel].site); seriesP.catch(() => {}); // the chart's series downloads while /readyz answers
  await onlineP;
  const [ms, series] = await Promise.all([Promise.all(list.map(metricsFor)), seriesP]);
  if (rev !== drawRev) return; // a newer draw started meanwhile: it paints
  const judged = ms.map(m => judge(m, rules));
  const verdict = verdictOf(judged, ms.map(m => m?.bothPct ?? null));
  const L = (i: number) => LETTERS[i];
  const cur = ms[sel];
  ctxSeal = cur ? cur.seal : "N/D";
  paintContext();

  // verdict (layer card): answer = sentence, why = reasons, proof = rules + sources
  const reasons = one(
    <div>{list.map((_, i) => {
      const j = judged[i];
      if (j.status === "nd") return <p class="mp-label">{t("cmp.why.nd", { L: L(i) })}</p>;
      if (j.status === "pass") return <p class="mp-label">{t("cmp.why.ok", { L: L(i) })}</p>;
      return <>{j.reasons.map(r => <p class="mp-label">{t("cmp.why." + r.key, { L: L(i), v: fmtNum(r.value, 0), lim: fmtNum(r.limit, 0) })}</p>)}</>;
    })}</div>);
  const answer = verdict.kind === "single" ? t("cmp.v.single", { L: L(verdict.winners[0]) })
    : verdict.kind === "multi" ? t("cmp.v.multi", { L: L(verdict.best as number) }) : verdict.kind === "none" ? t("cmp.v.none") : t("cmp.v.nodata");
  const proof = one(<div>{proofTable(list, ms, rules)}{editor(list, rules)}</div>);
  const card = createLayerCard({ id: "verdict", title: t("cmp.q"), status: statusOf(ms), answer, why: reasons, proof, layer: st.layer, onLayer: (layer: Layer) => setState({ layer }) });
  const actions = one(
    <div class="mp-actions">
      <a class="mp-pill is-primary" href={recoverHref(list)}>{t("cmp.delay", { L: L(sel) })}</a>
      {/* AUD-01: the chosen scenario, not the global one */}
      {judged[sel].status === "pass" ? <a class="mp-pill is-sim" href={hrefTo("landing.html", { ...getState(), site: list[sel].site, start: list[sel].start, hours: list[sel].hours })}>{t("cmp.land")}</a> : <button class="mp-pill" type="button" onClick={() => setState({ layer: "why" })}>{t("cmp.viewFailures")}</button>}
    </div>);
  card.el.insertBefore(actions, card.el.querySelector(".mp-chips"));

  // scenario list
  const ul: HTMLElement = one(
    <div class="mp-scn-list" role="radiogroup" aria-label={t("cmp.q")}>{list.map((sc, i) => (
      <button class={"mp-scn" + (judged[i].status === "pass" ? " is-eligible" : "")} type="button" role="radio" aria-checked={i === sel} tabIndex={i === sel ? 0 : -1}
        onClick={() => { sel = i; draw(); }}
        onKeyDown={(e: KeyboardEvent) => { const d = e.key === "ArrowDown" || e.key === "ArrowRight" ? 1 : e.key === "ArrowUp" || e.key === "ArrowLeft" ? -1 : 0; if (d) { e.preventDefault(); sel = (i + d + list.length) % list.length; draw().then(() => (ul.querySelector('[aria-checked="true"]') as HTMLElement | null)?.focus()); } }}>
        <span class="mp-scn-letter">{L(i)}</span>
        <span class="mp-scn-name">{`${(siteOf(sc.site) as CmpSite).name}`}<small>{`${(siteOf(sc.site) as CmpSite).n} · ${fmtDate(Date.parse(sc.start))}`}</small></span>
        {badge(judged[i])}
      </button>
    ))}</div>);

  // chart for selected scenario
  const fl = flagsOf(series, Date.parse(list[sel].start), list[sel].hours);
  const sunD = dailyFractions(fl.sun.map(v => v)), earthD = dailyFractions(fl.earth.map(v => v));
  const eb = barEl(earthD, "var(--earth)"); eb.classList.add("is-mirror");
  const chart = one(
    <section class="mp-card mp-cmp-time">
      <h3>{t("cmp.chart", { L: L(sel) })}</h3>
      <div class="mp-day-chart">
        <div class="mp-legend">{([["sun", "cmp.sun"], ["earth", "cmp.earth"]] as [string, string][]).map(([k, key]) => <span><i class={"sw " + k}></i>{t(key)}</span>)}</div>
        <Node node={barEl(sunD, "var(--sun)")} /><Node node={eb} />
        <div class="mp-axis"><span>D0</span><span>{"D" + Math.ceil((sunD.length - 1) / 2)}</span><span>{"D" + (sunD.length - 1)}</span></div>
      </div>
    </section>);

  $("left").replaceChildren(card.el, ul, chart);
  $("right").replaceChildren(diffCard(list, ms, rules));
  drawDock(list); terrain && terrain.select(list[sel].site); markRoute();
}
function statusOf(ms: Metrics[]): string | null { const m = ms.find(Boolean); return m ? m.status : "NO_SERIES_DATA"; }
function recoverHref(list: Scenario[]): string { return hrefTo("recover.html") + "#" + buildHash({ sc: [list[sel]] }); }
function badge(j: Judged): ComponentChild {
  if (j.status === "nd") return <span class="mp-badge is-nd">{t("cmp.nd")}</span>;
  if (j.status === "pass") return <span class="mp-badge">{t("cmp.pass")}</span>;
  return <span class="mp-badge is-fail">{t("cmp.fail." + j.reasons[0].key)}</span>;
}
interface RowOpts { lower?: boolean; failIf?: ((v: number) => boolean) | null; fmt?: (x: number | null | undefined) => string }
function diffCard(list: Scenario[], ms: Metrics[], rules: LimitRules): HTMLElement {
  const best = (vals: (number | null)[], lower: boolean): number | null => { const f = vals.filter((v): v is number => v != null); if (!f.length) return null; return lower ? Math.min(...f) : Math.max(...f); };
  const group = (label: string, rule: string) => <tr class="grp"><th colSpan={list.length + 1}>{label}<small>{"• " + rule}</small></th></tr>;
  const row = (label: string, get: (m: NonNullable<Metrics>) => number | null | undefined, { lower = false, failIf = null, fmt = hv }: RowOpts = {}) => {
    const vals = ms.map(m => (m ? get(m) ?? null : null)), b = best(vals, lower);
    return (
      <tr><th scope="row">{label}</th>{vals.map(v => (
        <td class={v == null ? undefined : failIf && failIf(v) ? "is-fail" : v === b && vals.filter(x => x === b).length < vals.length ? "is-best" : undefined}>{fmt(v)}</td>
      ))}</tr>
    );
  };
  const sl = ms.map(m => slack(m, rules));
  const bs = best(sl, false);
  return one(
    <section class="mp-card">
      <div class="mp-foot" style={{ justifyContent: "space-between", marginTop: "0" }}>
        <h3>{t("cmp.diff")}</h3>
        <button class="mp-chipg" type="button" onClick={() => setState({ layer: "proof" })}>{t("cmp.full")}</button>
      </div>
      <table class="mp-diff">
        <thead><tr><th></th>{list.map((_, i) => <th scope="col" aria-current={i === sel ? "true" : undefined}>{LETTERS[i]}</th>)}</tr></thead>
        <tbody>
          {group(t("cmp.power"), t("cmp.rule.night", { n: fmtNum(rules.night) }) + " (" + t("cmp.assumed") + ")")}
          {row(t("cmp.row.sun"), m => m.sunPct, { fmt: pv })}
          {row(t("cmp.row.night"), m => m.dark, { lower: true, failIf: v => v > rules.night })}
          <tr><th scope="row">{t("cmp.row.slack")}</th>{sl.map(v => (
            <td class={v == null ? undefined : v < 0 ? "is-fail" : v === bs && sl.filter(x => x === bs).length < sl.length ? "is-best" : undefined}>{v == null ? t("nd") : (v > 0 ? "+" : "") + hv(v)}</td>
          ))}</tr>
          <tr><th scope="row">{t("cmp.row.battery")}</th>{ms.map(() => <td title={t("cmp.battery.nd")}>{t("nd")}</td>)}</tr>
          {group(t("cmp.contact"), t("cmp.rule.blackout", { n: fmtNum(rules.blackout) }) + " (" + t("cmp.assumed") + ")")}
          {row(t("cmp.row.earth"), m => m.earthPct, { fmt: pv })}
          {row(t("cmp.row.loss"), m => m.blackout, { lower: true, failIf: v => v > rules.blackout })}
          {row(t("cmp.row.both"), m => m.bothPct, { fmt: pv })}
        </tbody>
      </table>
      <div class="mp-foot">{ndSeal()}<span class="mp-label">{t("cmp.rocks")}</span></div>
    </section>);
}
function proofTable(list: Scenario[], ms: Metrics[], rules: LimitRules): ComponentChild {
  const add = (k: string, v: ComponentChild) => <tr><th scope="row">{k}</th><td>{v}</td></tr>;
  return (
    <table class="mp-proof"><tbody>
      {add(t("cmp.def"), t("cmp.def.txt"))}
      {list.map((_, i) => {
        const m = ms[i];
        return add(`${LETTERS[i]} · ${t("cmp.src")}`, m
          ? <span>{(m.origin === "api" ? t("cmp.src.api") : t("cmp.src.static")) + " · "}<Node node={sealEl(m.seal)} />{` ${m.status || ""}`}{m.sha ? <><br /><code class="mp-coord">{m.sha}</code></> : null}</span>
          : <span>{t("cmp.outside")}{" "}{ndSeal()}</span>);
      })}
      {add(t("cmp.rules"), t("cmp.assumed") + `: ${fmtNum(rules.night)} h · ${fmtNum(rules.blackout)} h`)}
    </tbody></table>
  );
}
function editor(list: Scenario[], rules: LimitRules): ComponentChild {
  return (
    <div class="mp-edit">
      {list.map((sc, i) => {
        const upd = (e: Event) => {
          const r = (e.currentTarget as HTMLElement).parentElement as HTMLElement;
          const s = r.querySelector("select") as HTMLSelectElement, d = r.querySelector('input[type="date"]') as HTMLInputElement, hh = r.querySelector('input[type="number"]') as HTMLInputElement;
          const nl = list.map(x => ({ ...x })); const dv = d.value ? d.value + "T00:00:00Z" : sc.start; nl[i] = { site: s.value, start: dv, hours: Math.max(DAY, Number(hh.value) || sc.hours) }; save(nl);
        };
        return (
          <div class="mp-edit-row"><b>{LETTERS[i]}</b>
            <select aria-label={t("cmp.site")} onChange={upd}>{doc.sites.map(x => <option value={x.id} selected={x.id === sc.site}>{`${x.n} · ${x.name}`}</option>)}</select>
            <input type="date" value={sc.start.slice(0, 10)} aria-label={t("cmp.start")} onChange={upd} />
            <input type="number" min={String(DAY)} step={String(DAY)} value={String(sc.hours)} aria-label={t("cmp.hours")} onChange={upd} />
            {list.length > 1 ? <button class="mp-pill" type="button" onClick={() => save(list.filter((_, k) => k !== i))}>{t("cmp.remove")}</button> : null}
          </div>
        );
      })}
      {list.length < MAXSC ? <button class="mp-pill" type="button" onClick={() => save([...list, { ...list[list.length - 1] }])}>{"+ " + t("cmp.add")}</button> : null}
      <div class="mp-edit-row">{(["night", "blackout"] as const).map(key => (
        <label class="mp-label">{t("cmp.rule." + key + ".l") + " "}<input type="number" min="1" value={String(rules[key])}
          onChange={(e: Event) => { const v = Number((e.currentTarget as HTMLInputElement).value); if (v > 0) setState({ [key]: v }); }} /></label>
      ))}</div>
    </div>
  );
}
function drawDock(list: Scenario[]) {
  const b = (txt: string, aria: string, fn: () => void) => <button class="mp-pill" type="button" aria-label={aria} onClick={fn}>{txt}</button>;
  $("dock").replaceChildren(...build(
    <>
      {b("‹", t("cmp.prev"), () => { sel = (sel + list.length - 1) % list.length; draw(); })}
      {b("›", t("cmp.next"), () => { sel = (sel + 1) % list.length; draw(); })}
      <select class="mp-pill is-primary" aria-label={t("cmp.scenario", { L: "" })} onChange={(e: Event) => { sel = Number((e.currentTarget as HTMLSelectElement).value); draw(); }}>
        {list.map((_, i) => <option value={String(i)} selected={i === sel}>{t("cmp.scenario", { L: LETTERS[i] })}</option>)}
      </select>
      {b("+", t("cmp.add"), () => { if (list.length < MAXSC) save([...list, { ...list[sel] }]); })}
    </>));
}
// Imperative on purpose: core/terrain.js rebuilds the markers on every redraw, so they are relabelled in place.
function markRoute() {
  const list = scenarios();
  document.querySelectorAll<HTMLElement>(".mp-marker").forEach(m => { const idx = list.findIndex(s => s.site === m.dataset.site); m.hidden = idx < 0; if (idx >= 0) { const letters = list.map((s, i) => s.site === m.dataset.site ? LETTERS[i] : null).filter(Boolean).join("/"); (m.firstChild as ChildNode).textContent = letters; } });
}
let terrain: { select(id: string): void } | null = null;
paintContext();
await afterPaint(document.querySelector(".mp-ctx-text"));
// After the paint, in parallel: the visible scenarios' series and API figures (draw) and the map (its relief draws when the heights arrive).
const first = draw().catch(() => { $("left").replaceChildren(one(<p class="mp-label">{t("nd")}</p>)); });
terrain = await mountTerrain($("terrain"), { sites: doc.sites, selected: scenarios()[0].site, progressive: true,
  route: [...new Set(scenarios().map(s => s.site))], onSelect: (id: string) => { const i = scenarios().findIndex(s => s.site === id); if (i >= 0) { sel = i; draw(); } } });
new MutationObserver(() => markRoute()).observe($("terrain"), { childList: true, subtree: true });
markRoute();
await first;
terrain.select(scenarios()[sel].site); markRoute();
onState(() => draw());
addEventListener("hashchange", () => draw());
